def _timezone_required(value: datetime, field_name: str) -> datetime:
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError(f"{field_name} must include a timezone")
    return value


def _safe_manifest_path(value: str) -> str:
    if not value or "\x00" in value or "\\" in value:
        raise ValueError("artifact path must be a non-empty POSIX relative path")
    path = PurePosixPath(value)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise ValueError("artifact path must remain within the capture root")
    if any(character in value for character in "*?[]{}"):
        raise ValueError("artifact path cannot contain glob characters")
    return path.as_posix()


