class DeviceProfile(StrictFrozenModel):
    schema_version: Literal["doctor_v2_device_profile_v1"] = "doctor_v2_device_profile_v1"
    profile_id: NonEmptyText
    status: DeviceProfileStatus
    device_model: NonEmptyText
    firmware_version: NonEmptyText
    lens_id: NonEmptyText
    sensor_width_px: PositiveInt
    sensor_height_px: PositiveInt
    calibration_version: NonEmptyText
    supported_channels: tuple[ChannelRole, ...]
    channel_role_mapping: tuple[DeviceChannelMapping, ...]
    manifest_key_ids: tuple[NonEmptyText, ...]
    qc_attestation_key_ids: tuple[NonEmptyText, ...]
    approved_viewpoints: tuple[Viewpoint, ...] = (Viewpoint.FRONT_M,)

    @model_validator(mode="after")
    def validate_profile(self) -> "DeviceProfile":
        supported = set(self.supported_channels)
        if len(supported) != len(self.supported_channels):
            raise ValueError("supported_channels must be unique")
        if ChannelRole.RGB not in supported:
            raise ValueError("every clinic DeviceProfile must support RGB")
        mapping_roles = [item.role for item in self.channel_role_mapping]
        if set(mapping_roles) != supported or len(mapping_roles) != len(set(mapping_roles)):
            raise ValueError("channel_role_mapping must exactly cover supported_channels")
        if not self.manifest_key_ids or len(set(self.manifest_key_ids)) != len(self.manifest_key_ids):
            raise ValueError("manifest_key_ids must be non-empty and unique")
        if not self.qc_attestation_key_ids or len(set(self.qc_attestation_key_ids)) != len(
            self.qc_attestation_key_ids
        ):
            raise ValueError("qc_attestation_key_ids must be non-empty and unique")
        if not self.approved_viewpoints or len(set(self.approved_viewpoints)) != len(self.approved_viewpoints):
            raise ValueError("approved_viewpoints must be non-empty and unique")
        return self

    def content_sha256(self) -> str:
        return content_sha256(self)

    def device_channel_name(self, role: ChannelRole) -> str:
        for mapping in self.channel_role_mapping:
            if mapping.role is role:
                return mapping.device_channel_name
        raise KeyError(role)


class TrustedSigningKey(StrictFrozenModel):
    key_id: NonEmptyText
    purpose: SigningKeyPurpose
    public_key_hex: Ed25519PublicKeyHex
    issuer_id: NonEmptyText
    valid_from: datetime
    valid_until: datetime
    allowed_evidence_sources: tuple[NonEmptyText, ...] = ()
    revoked: StrictBool = False

    @field_validator("valid_from", "valid_until")
    @classmethod
    def validate_key_time(cls, value: datetime) -> datetime:
        return _timezone_required(value, "signing key validity")

    @model_validator(mode="after")
    def validate_key_policy(self) -> "TrustedSigningKey":
        if self.valid_until <= self.valid_from:
            raise ValueError("signing key valid_until must be later than valid_from")
        if self.purpose is SigningKeyPurpose.QC_ATTESTATION:
            if not self.allowed_evidence_sources or len(set(self.allowed_evidence_sources)) != len(
                self.allowed_evidence_sources
            ):
                raise ValueError("QC attestation key requires unique allowed_evidence_sources")
        elif self.allowed_evidence_sources:
            raise ValueError("capture manifest key cannot authorize QC evidence sources")
        return self


