                raise ValueError("detector metrics must be valid canonical JSON") from exc
            if not isinstance(parsed, dict):
                raise ValueError("detector metrics JSON root must be an object")
            if canonical_json_bytes(parsed).decode("utf-8") != self.metrics_canonical_json:
                raise ValueError("detector metrics must use canonical JSON")
            if content_sha256(parsed) != self.metrics_sha256:
                raise ValueError("detector metrics SHA256 mismatch")
        return self

    def metrics_document(self) -> dict[str, Any] | None:
        if self.metrics_canonical_json is None:
            return None
        import json

        return json.loads(self.metrics_canonical_json)


class ClinicalModuleResult(StrictFrozenModel):
    schema_version: Literal["doctor_v2_clinical_module_result_v1"] = (
        "doctor_v2_clinical_module_result_v1"
    )
    requirement_id: Annotated[str, Field(pattern=r"^(0[1-9]|1[01])$")]
    module_state: ModuleState
    report_eligibility: ReportEligibility
    observations: tuple[DetectorObservation, ...] = ()
    formal_score: float | None = None
    formal_grade: NonEmptyText | None = None
    care_advice: tuple[NonEmptyText, ...] = ()
    medical_signoff_ref: NonEmptyText | None = None
    reason_codes: ReasonCodes = ()

    @model_validator(mode="after")
    def enforce_orthogonal_fail_closed_state(self) -> "ClinicalModuleResult":
        if any(item.requirement_id != self.requirement_id for item in self.observations):
            raise ValueError("all observations must belong to the same requirement")
        if self.module_state is ModuleState.NOT_ASSESSABLE:
            if self.report_eligibility is not ReportEligibility.NOT_REPORTABLE:
                raise ValueError("NOT_ASSESSABLE must be NOT_REPORTABLE")
            if not self.reason_codes:
                raise ValueError("NOT_ASSESSABLE requires a reason code")
        if self.report_eligibility is ReportEligibility.NOT_REPORTABLE:
            if self.formal_score is not None or self.formal_grade is not None or self.care_advice:
                raise ValueError("NOT_REPORTABLE cannot carry formal score, grade, or care advice")
        if self.report_eligibility is ReportEligibility.INTERNAL_ONLY:
            if self.formal_score is not None or self.formal_grade is not None or self.care_advice:
                raise ValueError("INTERNAL_ONLY cannot carry formal clinical outputs")
        if self.report_eligibility is ReportEligibility.CLINICAL_ELIGIBLE:
            if self.module_state is not ModuleState.MEDICAL_READY:
                raise ValueError("CLINICAL_ELIGIBLE requires MEDICAL_READY")
            if self.medical_signoff_ref is None:
                raise ValueError("CLINICAL_ELIGIBLE requires module medical signoff")
        if self.module_state is ModuleState.MEDICAL_READY:
            if not any(item.evidence_state is EvidenceState.MEDICAL_PASSED for item in self.observations):
                raise ValueError("MEDICAL_READY requires MEDICAL_PASSED evidence")
        if self.module_state is ModuleState.ENGINEERING_READY:
            if not any(item.evidence_state is EvidenceState.ENGINEERING_PASSED for item in self.observations):
                raise ValueError("ENGINEERING_READY requires ENGINEERING_PASSED evidence")
            if self.report_eligibility is ReportEligibility.CLINICAL_ELIGIBLE:
                raise ValueError("engineering state cannot auto-promote to clinical eligibility")
        return self


