def _validate_centers(
    centers: tuple[LegacyPoreCenterV1, ...],
) -> None:
    if not isinstance(centers, tuple):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "legacy centers must be an immutable tuple",
        )
    seen_coordinates: set[tuple[int, int]] = set()
    for expected_id, center in enumerate(centers, start=1):
        if not isinstance(center, LegacyPoreCenterV1):
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                "every legacy center must use LegacyPoreCenterV1",
            )
        values = (
            center.stable_instance_id,
            center.x,
            center.y,
            center.legacy_radius_px,
        )
        if any(type(value) is not int for value in values):
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                "legacy center fields must be strict Python integers",
            )
        if center.stable_instance_id != expected_id:
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                "stable instance IDs must be continuous and match tuple order",
            )
        if not (
            0 <= center.x < PORE_ANALYSIS_SHAPE[1]
            and 0 <= center.y < PORE_ANALYSIS_SHAPE[0]
        ):
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                f"instance {expected_id} center escaped the analysis space",
            )
        if not (
            PORE_LEGACY_RADIUS_MIN
            <= center.legacy_radius_px
            <= PORE_LEGACY_RADIUS_MAX
        ):
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                f"instance {expected_id} legacy radius escaped the frozen range",
            )
        coordinate = (center.x, center.y)
        if coordinate in seen_coordinates:
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                "legacy centers must have unique integer coordinates",
            )
        seen_coordinates.add(coordinate)


def _validate_response_stack(response_stack: np.ndarray) -> np.ndarray:
    if not isinstance(response_stack, np.ndarray):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "response_stack must be a NumPy array",
        )
    if response_stack.shape != PORE_RESPONSE_STACK_SHAPE:
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            f"response_stack must have shape {PORE_RESPONSE_STACK_SHAPE}",
        )
    if response_stack.dtype != np.float32:
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "response_stack must use float32",
        )
    if not np.all(np.isfinite(response_stack)):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "response_stack must contain only finite values",
        )
    if np.any(response_stack < 0.0) or np.any(response_stack > 1.0):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "normalized black-hat response must stay inside [0,1]",
        )
    return response_stack


