        )
    if set(valid_region_masks) != set(PoreRegionId):
        raise _fail(
            Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
            "valid_region_masks must contain all nine regions exactly once",
        )
    region_bools = {
        region_id: _validate_binary_mask(
            valid_region_masks[region_id],
            label=f"valid_region_masks[{region_id.value}]",
        )
        for region_id in PoreRegionId
    }
    occupancy = np.sum(np.stack(tuple(region_bools.values())), axis=0)
