def aggregate_pore_metrics_v1(
    *,
    valid_regions: PoreValidRegionSetV1,
    support_result: PoreSupportResultV1,
    legacy_metric_snapshots: tuple[LegacyPoreMetricSnapshotV1, ...],
) -> PoreMetricsResultV1:
    """Aggregate Stage5 A01 engineering metrics without image or file access."""

    _validate_valid_region_set(valid_regions)
    _validate_support_result(support_result)
    if not np.array_equal(
        valid_regions.valid_denominator_mask,
        support_result.valid_denominator_mask,
    ):
        raise _fail(
            Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
            "metrics denominator differs from support denominator",
        )
    snapshots = _validate_metric_snapshots(
        legacy_metric_snapshots,
        expected_count=len(support_result.instances),
    )

    instance_evidence: list[PoreInstanceEvidenceV1] = []
    label_map = support_result.instance_label_map
    for instance in support_result.instances:
        center_regions = tuple(
            region_id
            for region_id in PoreRegionId
            if valid_regions.valid_region_masks[region_id][
                instance.center_y,
                instance.center_x,
            ]
            > 0
        )
        if center_regions != (instance.center_region_id,):
            raise _fail(
                Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
                f"instance {instance.stable_instance_id} center-region binding drifted",
            )
        label_pixels = label_map == instance.stable_instance_id
        circularity, aspect_ratio = _recompute_shape_metrics(label_pixels)
        if not (
            math.isclose(circularity, instance.circularity, abs_tol=1e-12)
            and math.isclose(aspect_ratio, instance.aspect_ratio, abs_tol=1e-12)
        ):
            raise _fail(
                Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
                f"instance {instance.stable_instance_id} morphology drifted from label",
            )
        covered_regions = tuple(
            region_id
            for region_id in PoreRegionId
            if np.any(label_pixels & (valid_regions.valid_region_masks[region_id] > 0))
        )
        if covered_regions != instance.covered_region_ids:
            raise _fail(
                Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
                f"instance {instance.stable_instance_id} covered regions drifted",
            )
        instance_evidence.append(
            PoreInstanceEvidenceV1(
                stable_instance_id=instance.stable_instance_id,
                center_x=instance.center_x,
                center_y=instance.center_y,
                legacy_radius_px=instance.legacy_radius_px,
                selected_scale_index=instance.selected_scale_index,
                selected_kernel_size_px=instance.selected_kernel_size_px,
                center_peak_response=instance.center_peak_response,
                support_threshold=instance.support_threshold,
                candidate_area_px=instance.candidate_area_px,
                center_region_id=instance.center_region_id,
                covered_region_ids=instance.covered_region_ids,
                center_ring_contrast=snapshots[
                    instance.stable_instance_id
                ].center_ring_contrast,
                final_area_px=instance.final_area_px,
                circularity=circularity,
                aspect_ratio=aspect_ratio,
                boundary_crossing=instance.boundary_crossing,
            )
        )

    for region_id in PoreRegionId:
        mask = valid_regions.valid_region_masks[region_id]
        if (
            _raw_sha256(mask) != valid_regions.valid_region_raw_sha256[region_id]
            or int(np.count_nonzero(mask)) != valid_regions.valid_area_px[region_id]
        else 1.0
    )
    if not math.isfinite(circularity) or not math.isfinite(aspect_ratio):
        raise _fail(
            Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
            "final instance morphology must be finite",
        )
    return circularity, aspect_ratio


def build_pore_support_v1(
    *,
    response_stack: np.ndarray,
    centers: tuple[LegacyPoreCenterV1, ...],
    analysis_roi_mask: np.ndarray,
    valid_skin_mask: np.ndarray,
    feature_exclusion_mask: np.ndarray,
    postprocess_exclusion_mask: np.ndarray,
    valid_region_masks: Mapping[PoreRegionId, np.ndarray],
) -> PoreSupportResultV1:
    """Build unique Stage5 pore support from already-computed in-memory inputs."""

    response = _validate_response_stack(response_stack)
    _validate_centers(centers)
    analysis_roi = _validate_binary_mask(
        analysis_roi_mask,
        label="analysis_roi_mask",
    )
    valid_skin = _validate_binary_mask(valid_skin_mask, label="valid_skin_mask")
    feature_exclusion = _validate_binary_mask(
        feature_exclusion_mask,
        label="feature_exclusion_mask",
    )
    postprocess_exclusion = _validate_binary_mask(
        postprocess_exclusion_mask,
        label="postprocess_exclusion_mask",
    )
    valid_denominator = analysis_roi & valid_skin
    if int(np.count_nonzero(valid_denominator)) < PORE_MIN_DENOMINATOR_AREA_PX:
        raise _fail(
            Stage5PoresReasonCode.REGION_GEOMETRY_FAILED,
            "Stage5 denominator contains fewer than 500 pixels",
        )
    region_bools = _validate_regions(
        valid_region_masks=valid_region_masks,
        expected_denominator=valid_denominator,
    )
    valid_claim = (
        valid_denominator
        & ~feature_exclusion
        & ~postprocess_exclusion
    )

    candidates = tuple(
        _candidate_claim(
            response_stack=response,
            valid_claim=valid_claim,
            center=center,
        )
        for center in centers
    )
    label_map = _arbitrate_claims(candidates)
    support_bool = label_map > 0
    if np.any(support_bool & ~valid_claim):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_SUBSET_VIOLATION,
            "final support escaped the valid claim domain",
        )
    actual_ids = set(np.unique(label_map).tolist()) - {0}
    expected_ids = {center.stable_instance_id for center in centers}
    if actual_ids != expected_ids:
        raise _fail(
            Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
            "final label IDs differ from the stable legacy instance IDs",
        )

    instances: list[PoreInstanceSupportV1] = []
    for candidate in candidates:
        center = candidate.center
        if int(label_map[center.y, center.x]) != center.stable_instance_id:
            raise _fail(
                Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
                f"instance {center.stable_instance_id} lost its center pixel",
            )
        local_final = (
            label_map[
                candidate.y0 : candidate.y1,
                candidate.x0 : candidate.x1,
            ]
            == center.stable_instance_id
        )
        raise _fail(
            Stage5PoresReasonCode.REGION_GEOMETRY_FAILED,
            "valid denominator is smaller than the frozen 500-pixel hard gate",
        )
    if np.any(valid_denominator & ~anatomical_union):
        raise _fail(
            Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
            "analysis denominator escapes the anatomical nine-region union",
        )

    valid_masks: dict[PoreRegionId, np.ndarray] = {}
    valid_area: dict[PoreRegionId, int] = {}
    valid_coverage: dict[PoreRegionId, float] = {}
    valid_hashes: dict[PoreRegionId, str] = {}
    rebuilt_union = np.zeros(PORE_ANALYSIS_SHAPE, dtype=bool)
    for region_id in PoreRegionId:
        region = anatomical_bools[region_id] & valid_denominator
        rebuilt_union |= region
        encoded = _readonly_array(region.astype(np.uint8) * 255, dtype=np.uint8)
        area = int(np.count_nonzero(region))
        valid_masks[region_id] = encoded
        valid_area[region_id] = area
        valid_coverage[region_id] = float(area / anatomical_area[region_id])
        valid_hashes[region_id] = _raw_sha256(encoded)
    if not np.array_equal(rebuilt_union, valid_denominator):
        raise _fail(
            Stage5PoresReasonCode.REGION_ONTOLOGY_INCOMPLETE,
            "valid regions do not add back exactly to the analysis denominator",
        )

    encoded_denominator = _readonly_array(
        valid_denominator.astype(np.uint8) * 255,
        dtype=np.uint8,
    )
    return PoreValidRegionSetV1(
        valid_denominator_mask=encoded_denominator,
        anatomical_region_masks=MappingProxyType(anatomical_masks),
        valid_region_masks=MappingProxyType(valid_masks),
        anatomical_area_px=MappingProxyType(anatomical_area),
        valid_area_px=MappingProxyType(valid_area),
        valid_coverage_ratio=MappingProxyType(valid_coverage),
        anatomical_union_area_px=int(np.count_nonzero(anatomical_union)),
        valid_denominator_area_px=denominator_area,
        valid_denominator_raw_sha256=_raw_sha256(encoded_denominator),
        anatomical_region_raw_sha256=MappingProxyType(anatomical_hashes),
        valid_region_raw_sha256=MappingProxyType(valid_hashes),
    )


def _validate_support_result(result: PoreSupportResultV1) -> None:
    if not isinstance(result, PoreSupportResultV1):
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "support_result must be PoreSupportResultV1",
        )
    if result.algorithm_version != PORE_SUPPORT_ALGORITHM_VERSION:
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "support_result algorithm version drifted",
        )
    if result.response_kernel_sizes != PORE_RESPONSE_KERNEL_SIZES:
        raise _fail(
            Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
            "support_result response kernel order drifted",
        )
    binary_arrays = (
        ("valid_denominator_mask", result.valid_denominator_mask),
        ("valid_claim_mask", result.valid_claim_mask),
        ("evidence_support_mask", result.evidence_support_mask),
    )
    for label, array in binary_arrays:
        _validate_binary_mask(array, label=label)
        if not array.flags.c_contiguous or array.flags.writeable:
            raise _fail(
                Stage5PoresReasonCode.SUPPORT_INPUT_INVALID,
                f"{label} must be C-contiguous and read-only",
            )
    label_map = result.instance_label_map
    if (
        not isinstance(label_map, np.ndarray)
        or label_map.shape != PORE_ANALYSIS_SHAPE
        or label_map.dtype != np.dtype("<u4")
        or not label_map.flags.c_contiguous
        or label_map.flags.writeable
    ):
        raise _fail(
            Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
            "instance_label_map must be read-only C-contiguous little-endian uint32",
        )
    if not np.array_equal(result.evidence_support_mask > 0, label_map > 0):
        raise _fail(
            Stage5PoresReasonCode.LABEL_SUPPORT_INCONSISTENT,
            "support and label occupancy disagree",
        )
