void RegisterHttpRoutes(httplib::Server& server, JobManager& jobs,
                        const Config& config) {
  server.set_payload_max_length(config.max_image_bytes * 12U + 1024U * 1024U);

  server.Get("/health", [&](const httplib::Request&, httplib::Response& response) {
    const bool cascade = std::filesystem::is_regular_file(config.face_cascade_path);
    const bool calibration =
        std::filesystem::is_regular_file(config.skin_calibration_path);
    const bool profiles =
        std::filesystem::is_regular_file(config.skin_device_profiles_path);
    const bool vendor = std::filesystem::is_regular_file(config.vendor_skin_exe_path);
    Json(response, 200,
         {{"status", cascade && calibration && profiles ? "ready" : "not_ready"},
          {"language", "C++20"},
          {"offline", true},
          {"single_rgb", cascade && calibration && profiles},
          {"vendor_multispectral", vendor},
          {"measurement_grade", false},
          {"diagnostic_grade", false}});
  });

  server.Get("/v1/skin-maps/capabilities",
             [&](const httplib::Request&, httplib::Response& response) {
    Json(response, 200, DetectionCatalog::Capabilities());
  });

  server.Post("/v1/skin-maps/rgb",
              [&](const httplib::Request& request, httplib::Response& response) {
    Guard(response, [&] {
      if (!request.has_file("image")) {
        throw Error("RGB_IMAGE_REQUIRED",
                    "Upload one front image field named 'image'.", 422);
      }
      const auto& file = request.get_file_value("image");
      const std::string extension = LowerExtension(file.filename);
      if (extension != ".jpg" && extension != ".jpeg" && extension != ".png") {
        throw Error("UNSUPPORTED_IMAGE_TYPE", "Only JPG and PNG images are accepted.",
                    415, {{"filename", file.filename}});
      }
      const auto record = jobs.Create("skin_rgb");
      const std::string job_id = record.at("job_id").get<std::string>();
      try {
        const auto input = jobs.JobDirectory(job_id) / "input";
        SaveUpload(file, input / ("image" + extension), config.max_image_bytes);
        std::string profile = "generic";
        if (request.has_file("device_profile")) {
          profile = request.get_file_value("device_profile").content;
        } else if (request.has_param("device_profile")) {
          profile = request.get_param_value("device_profile");
        }
        SaveDeviceProfile(profile, input / "device_profile.txt");
        jobs.Submit(job_id);

