  [string]$VendorEngineRoot
)
$ErrorActionPreference = "Stop"
$Source = (Resolve-Path -LiteralPath $VendorEngineRoot).Path
$Executable = Join-Path $Source "XingerEngine.exe"
if (-not (Test-Path -LiteralPath $Executable -PathType Leaf)) {
  throw "XingerEngine.exe was not found in: $Source"
}
if (-not $env:LOCALAPPDATA) { throw "LOCALAPPDATA is unavailable." }
$Link = Join-Path $env:LOCALAPPDATA "SkinMapLocal\VendorEngine"
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Link) | Out-Null
if (Test-Path -LiteralPath $Link) {
  $Item = Get-Item -LiteralPath $Link
  if ($Item.LinkType -ne "Junction" -or $Item.Target -notcontains $Source) {
    throw "The ASCII vendor path exists but is not the expected junction: $Link"
  }
} else {
  New-Item -ItemType Junction -Path $Link -Target $Source | Out-Null
}
Write-Output "Vendor Engine junction is ready: $Link"
Write-Output "Set SKINMAP_VENDOR_ENGINE_ROOT=$Link if an explicit path is required."

