from src.doctor_v2.canonical import canonical_json_bytes, content_sha256, file_sha256
from src.doctor_v2.existing_delivery import assemble_existing_three_report_delivery


PROJECT_ROOT = Path(__file__).resolve().parents[1]
CAPTURE_ORDER = ("clinic28-25", "clinic28-09", "clinic28-23")
