    parser.add_argument("--clinic25-formal-root", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()

    output = args.output
    output.mkdir(parents=True, exist_ok=False)
    code_rows, code_hash = _code_state()
    fixture_rgb, fixture_manifest_sha = _fixture_rgb_hashes(args.fixture_root)
    samples: list[dict[str, object]] = []

    for alias in CAPTURE_ORDER:
        if alias == "clinic28-25":
            nine_root = args.clinic25_nine_root
            formal_root = args.clinic25_formal_root
        else:
            nine_root = args.nine_root / alias
            formal_root = args.formal_root / alias
        input_path = nine_root / "00_输入图片.jpg"
        input_sha = file_sha256(input_path)
        if input_sha != fixture_rgb[alias]:
            raise ValueError(f"nine-result RGB differs from Clinic-Fast3 fixture: {alias}")

        bundle, receipt_path = assemble_existing_three_report_delivery(
            capture_alias=alias,
