from __future__ import annotations

import re
from datetime import datetime
from pathlib import PurePosixPath
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


ChannelRole = Literal["RGB", "PP", "CP", "365"]
RegistrationState = Literal["ANCHOR", "PASSED", "FAILED", "ABSENT", "NOT_REQUIRED"]
LogicalResultId = Literal[
    "redness",
    "spots",
    "brown",
    "texture",
    "pores",
    "uv_spots",
    "porphyrin",
    "wrinkle",
    "acne",
]


class _Frozen(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


def safe_relative_path(value: str) -> str:
    path = PurePosixPath(value)
    if (
        not value
        or "\\" in value
        or "\x00" in value
        or path.is_absolute()
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise ValueError("path must be a safe POSIX relative path")
    return path.as_posix()


class EvidenceArtifact(_Frozen):
    relative_path: str
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    size_bytes: int = Field(gt=0)
    media_type: str
    coordinate_space: str
    width: int | None = Field(default=None, gt=0)
    height: int | None = Field(default=None, gt=0)

    @field_validator("relative_path")
    @classmethod
    def validate_relative_path(cls, value: str) -> str:
        return safe_relative_path(value)

    @model_validator(mode="after")
    def validate_image_shape(self) -> "EvidenceArtifact":
        if (self.width is None) != (self.height is None):
            raise ValueError("image width and height must be present together")
        return self


class ChannelEvidenceState(_Frozen):
    role: ChannelRole
    decode_status: Literal["PASSED", "FAILED", "ABSENT"]
    preprocess_status: Literal["PASS", "FAILED", "NOT_RUN"]
    registration_status: RegistrationState
    registration_transform_sha256: str | None = Field(
        default=None, pattern=r"^[0-9a-f]{64}$"
    )
    input_sha256: str | None = Field(default=None, pattern=r"^[0-9a-f]{64}$")
    reason_codes: tuple[str, ...] = ()

    @model_validator(mode="after")
    def validate_registration(self) -> "ChannelEvidenceState":
        if self.role == "RGB":
            if self.registration_status != "ANCHOR":
                raise ValueError("RGB must be the registration anchor")
            if self.registration_transform_sha256 is not None:
                raise ValueError("RGB anchor cannot carry a transform")
        elif self.registration_status == "PASSED":
            if self.registration_transform_sha256 is None:
                raise ValueError("passed non-RGB registration requires a transform hash")
        elif self.registration_transform_sha256 is not None:
            raise ValueError("failed/absent/non-required registration cannot carry a transform")
        return self


class SourceResultRef(_Frozen):
    source_result_id: str
    logical_result_id: LogicalResultId
    source_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    source_relative_path: str
    source_role: Literal["PRIMARY", "AUXILIARY", "SHADOW"]
    algorithm_version: str

    @field_validator("source_relative_path")
    @classmethod
    def validate_source_path(cls, value: str) -> str:
        return safe_relative_path(value)


class NineResultRecord(_Frozen):
    logical_result_id: LogicalResultId
    source_result_id: str
    status: Literal["SUCCESS", "FAILED", "NOT_RUN"]
    channels: tuple[ChannelRole, ...]
    algorithm_version: str
    source_relative_path: str
    source_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    metrics: dict[str, Any] = {}
    units: dict[str, str] = {}
    artifacts: tuple[EvidenceArtifact, ...] = ()
    roi_id: str = "legacy_result_roi"
    support_mask_id: str | None = None
    denominator_name: str = "legacy_result_denominator"
    denominator_value: int | float | None = None
    denominator_unit: str = "not_normalized"
    legacy_score: int | float | None = None
    legacy_grade: str | None = None
    legacy_recommendation: str | None = None
    reason_codes: tuple[str, ...] = ()

    @field_validator("source_relative_path")
    @classmethod
    def validate_result_path(cls, value: str) -> str:
        return safe_relative_path(value)

    @model_validator(mode="after")
    def validate_failure(self) -> "NineResultRecord":
        if self.status != "SUCCESS" and not self.reason_codes:
            raise ValueError("failed/not-run nine-result record requires a reason code")
        return self


class NineResultBundle(_Frozen):
    schema_version: Literal["doctor_v2_nine_result_bundle_v1"] = (
        "doctor_v2_nine_result_bundle_v1"
    )
    capture_alias: str
    route: Literal["consumer_rgb", "clinic_four_light"]
    generated_at: datetime
    code_state_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    results: tuple[NineResultRecord, ...]
    scoring_trace_relative_path: str | None = None
    scoring_trace_sha256: str | None = Field(default=None, pattern=r"^[0-9a-f]{64}$")

    @field_validator("scoring_trace_relative_path")
    @classmethod
    def validate_trace_path(cls, value: str | None) -> str | None:
        return None if value is None else safe_relative_path(value)

    @model_validator(mode="after")
    def validate_nine_results(self) -> "NineResultBundle":
        expected = (
            "redness",
            "spots",
            "brown",
            "texture",
            "pores",
            "uv_spots",
            "porphyrin",
            "wrinkle",
            "acne",
        )
        actual = tuple(item.logical_result_id for item in self.results)
        if actual != expected:
            raise ValueError(f"nine-result bundle order drifted: {actual}")
        if len({item.source_result_id for item in self.results}) != 9:
            raise ValueError("nine-result source IDs must be unique")
        if (self.scoring_trace_relative_path is None) != (self.scoring_trace_sha256 is None):
            raise ValueError("scoring trace path and hash must be present together")
        return self


class Doctor11EvidenceHead(_Frozen):
    head_id: str
    title: str
    implementation_state: Literal["IMPLEMENTED", "ALGORITHM_FAILED", "NOT_IMPLEMENTED"]
    evidence_state: Literal["UNAVAILABLE", "SHADOW", "ENGINEERING_PASSED"]
    source_refs: tuple[SourceResultRef, ...] = ()
    channels: tuple[ChannelRole, ...]
    coordinate_space: str
    algorithm_version: str
    roi_id: str
    support_mask_id: str | None
    denominator_name: str
    denominator_value: int | float | None
    denominator_unit: str
    metrics: dict[str, Any]
    units: dict[str, str]
    regions: tuple[dict[str, Any], ...] = ()
    bilateral: tuple[dict[str, Any], ...] = ()
    artifacts: tuple[EvidenceArtifact, ...] = ()
    required_registrations: tuple[ChannelRole, ...] = ()
    required_registration_transforms: dict[ChannelRole, str] = {}
    registration_status: Literal["NOT_REQUIRED", "PASSED", "FAILED"]
    cross_metric_keys: tuple[str, ...] = ()
    overlap: dict[str, Any] | None = None
    co_location: dict[str, Any] | None = None
    fusion: dict[str, Any] | None = None
    reason_codes: tuple[str, ...] = ()

    @model_validator(mode="after")
    def validate_fail_closed(self) -> "Doctor11EvidenceHead":
        if self.evidence_state == "UNAVAILABLE" and not self.reason_codes:
            raise ValueError("unavailable evidence requires a reason code")
        if self.required_registrations and self.registration_status == "NOT_REQUIRED":
            raise ValueError("cross-channel head cannot bypass registration")
        if not self.required_registrations and self.registration_status != "NOT_REQUIRED":
            raise ValueError("single-channel head must use NOT_REQUIRED")
        if set(self.required_registration_transforms) - set(self.required_registrations):
            raise ValueError("transform binding exists for an undeclared registration dependency")
        if any(
            not re.fullmatch(r"[0-9a-f]{64}", value)
            for value in self.required_registration_transforms.values()
        ):
            raise ValueError("required registration transform must be a SHA256")
        if self.registration_status != "PASSED":
            if any(value is not None for value in (self.overlap, self.co_location, self.fusion)):
                raise ValueError("non-passed registration requires null cross-channel fields")
            leaked = [key for key in self.cross_metric_keys if self.metrics.get(key) is not None]
            if leaked:
                raise ValueError(f"non-passed registration leaked cross metrics: {leaked}")
        return self


class Doctor11ModuleRecord(_Frozen):
    requirement_id: str = Field(pattern=r"^(0[1-9]|1[01])$")
    title: str
    implementation_state: Literal["IMPLEMENTED", "PARTIAL_IMPLEMENTATION", "FAILED"]
    evidence_state: Literal["UNAVAILABLE", "SHADOW", "ENGINEERING_PASSED"]
    module_state: Literal["NOT_ASSESSABLE", "PARTIAL", "ENGINEERING_READY"]
    report_eligibility: Literal["NOT_REPORTABLE", "INTERNAL_ONLY"]
    medical_state: Literal["NOT_MEDICALLY_VALIDATED"] = "NOT_MEDICALLY_VALIDATED"
    evidence_heads: tuple[Doctor11EvidenceHead, ...]
    summary: str
    limitations: tuple[str, ...]
    reason_codes: tuple[str, ...] = ()
    score: None = None
    grade: None = None
    recommendation: None = None

    @model_validator(mode="after")
    def validate_module(self) -> "Doctor11ModuleRecord":
        if not self.evidence_heads or not self.limitations:
            raise ValueError("every Doctor11 module requires evidence and limitations")
        if self.module_state == "NOT_ASSESSABLE" and self.report_eligibility != "NOT_REPORTABLE":
            raise ValueError("not-assessable module must be not reportable")
        if self.requirement_id == "11" and self.module_state != "NOT_ASSESSABLE":
            raise ValueError("front-only contour evidence cannot assess the firmness construct")
        return self


