            "结果摘要": (
                "证据不足，当前不可评估；该状态不得解释为未发现问题。"
                if not_assessable else _formal_summary(source)
            ),
            "核心指标": [] if not_assessable else [_formal_metric(row, module_id=module_id) for row in source.get("核心指标", []) or [] if row.get("value") not in (None, "", "不可评估")],
            "分区指标": [] if not_assessable else _formal_regions(source.get("分区指标", []), module_id=module_id),
            "结果图": [] if not_assessable else [str(path) for path in [Path(value) for value in source.get("结果图", []) or []] if path.is_file()],
            "左右比较摘要": _formal_text(source.get("左右比较摘要", "")),
            "日常管理提示": advice if report_eligibility == "CLINICAL_ELIGIBLE" else "",
            "用户评估状态": display_status,
            "医生评估状态": display_status,
            "模块状态": module_status,
            "报告资格": report_eligibility,
            "证据状态": source.get("证据状态", "SHADOW"),
            "医生结果分组": [] if not_assessable else _doctor_groups(source),
            "正式评分说明": (
                _formal_score_explanation(source)
                if not strict_evidence_shortage or isinstance(score, (int, float))
                else {}
            ),
            "二维补充结果图": [
                str(path)
                for path in [Path(value) for value in source.get("二维补充结果图", []) or []]
                if path.is_file()
            ],
        }
        if not is_fast3 and module_id == "02":
            porphyrin = next((group for group in module["医生结果分组"] if group.get("title") == "紫质：现有量化结果"), None)
            if porphyrin:
                selected = {"紫质目标数量", "紫质单位面积密度", "紫质面积占比", "紫质P90强度"}
                module["核心指标"] = module["核心指标"][:3] + [row for row in porphyrin["metrics"] if row["name"] in selected][:1]
            _, _, _, lr_text, _ = _oil_distribution(source)
            module["左右比较摘要"] = lr_text
        elif not is_fast3 and module_id == "03":
            for row in module["核心指标"]:
                if row["name"] == "主要集中区域":
                    row["name"] = "可见色斑主要集中区域"
                    row["medical_name"] = row["name"]
                    row["display_type"], row["unit"] = _FULL_METRIC_OVERRIDES[row["name"]]
                    row["explanation"] = _metric_explanation(row, module_id=module_id)
            selected_names = {"可见斑点数量", "UV色斑数量", "棕色实例数量", "可见色斑主要集中区域"}
            selected = [row for row in module["核心指标"] if row["name"] in selected_names]
            module["核心指标"] = selected or module["核心指标"][:4]
            dominant, comparison, regions = _pigmentation_distribution(source)
            module["分区指标"] = regions
            module["左右比较摘要"] = comparison
        elif not is_fast3 and module_id == "04":
            official_groups = module["医生结果分组"]
            representative_names = {"弥漫红区面积占比", "P90红度", "红区连续性", "弥漫红区均匀度"}
