        input_sha = file_sha256(input_path)
        if input_sha != fixture_rgb[alias]:
            raise ValueError(f"nine-result RGB differs from Clinic-Fast3 fixture: {alias}")

        bundle, receipt_path = assemble_existing_three_report_delivery(
            capture_alias=alias,
