def _null_metric_keys(value: Any, keys: frozenset[str]) -> Any:
    """Return a detached metrics tree with every named cross metric nulled."""
    if isinstance(value, dict):
        return {
            key: None if key in keys else _null_metric_keys(item, keys)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [_null_metric_keys(item, keys) for item in value]
    if isinstance(value, tuple):
        return tuple(_null_metric_keys(item, keys) for item in value)
    return value


def gate_cross_channel_head(
    head: Doctor11EvidenceHead,
    channel_status: Iterable[ChannelEvidenceState],
) -> Doctor11EvidenceHead:
    """Bind every cross-channel claim to the actual capture registration receipt.

    The caller cannot supply a convenient ``PASSED`` flag.  A head passes only
    when every declared non-RGB dependency exists, has registration ``PASSED``
    and carries its frozen transform hash.  Independent single-channel evidence
    remains usable, but every cross field is always null.
    """

    states = {row.role: row for row in channel_status}
    required = tuple(dict.fromkeys(head.required_registrations))
    if not required:
        return head.model_copy(
            update={
                "registration_status": "NOT_REQUIRED",
                "overlap": None,
                "co_location": None,
                "fusion": None,
                "metrics": _null_metric_keys(head.metrics, frozenset(head.cross_metric_keys)),
            }
        )

    failures: list[str] = []
    for role in required:
        state = states.get(role)
        if state is None:
            failures.append(f"REGISTRATION_DEPENDENCY_{role}_ABSENT")
            continue
        if state.registration_status != "PASSED":
            failures.append(
                f"REGISTRATION_DEPENDENCY_{role}_{state.registration_status}"
            )
        elif state.registration_transform_sha256 is None:
            failures.append(f"REGISTRATION_DEPENDENCY_{role}_TRANSFORM_MISSING")
        else:
            expected = head.required_registration_transforms.get(role)
            if expected is None:
                failures.append(f"REGISTRATION_DEPENDENCY_{role}_HEAD_BINDING_MISSING")
            elif expected != state.registration_transform_sha256:
                failures.append(f"REGISTRATION_DEPENDENCY_{role}_TRANSFORM_HASH_MISMATCH")

    if failures:
        return head.model_copy(
            update={
                "registration_status": "FAILED",
                "evidence_state": (
                    "SHADOW" if head.evidence_state == "ENGINEERING_PASSED" else head.evidence_state
                ),
                "overlap": None,
                "co_location": None,
                "fusion": None,
                "metrics": _null_metric_keys(head.metrics, frozenset(head.cross_metric_keys)),
                "reason_codes": tuple(dict.fromkeys((*head.reason_codes, *failures))),
            }
        )
    return head.model_copy(update={"registration_status": "PASSED"})


def _source_ref(record: NineResultRecord, role: str) -> SourceResultRef:
    return SourceResultRef(
        source_result_id=record.source_result_id,
        logical_result_id=record.logical_result_id,
        source_sha256=record.source_sha256,
        source_relative_path=record.source_relative_path,
        source_role=role,
        algorithm_version=record.algorithm_version,
    )


def _head_from_nine_result(
    record: NineResultRecord,
    role: str,
    module_id: str,
) -> Doctor11EvidenceHead:
    available = record.status == "SUCCESS"
    head_id, title = _NINE_HEAD_NAMES.get(
        (module_id, record.logical_result_id),
        (f"nine_result_{record.logical_result_id}", f"现有九项结果：{record.logical_result_id}"),
    )
    projection = (
        record.doctor11_dimension_projections.get(module_id)
        if record.logical_result_id == "wrinkle" and module_id in {"08", "09"}
        else None
    )
    projection_metrics = dict(projection.metrics) if projection is not None else {}
    projection_regions = tuple(projection.regions) if projection is not None else ()
    projection_denominator = projection_metrics.get("valid_skin_area_px")
    expected_scope = f"doctor_v2_{module_id}_legacy_wrinkle_regions"
    expected_version = "wrinkle_doctor11_region_projection_v1"
    expected_region_names = (
        tuple(REGION_GROUPS[module_id]["region_names"])
        if module_id in {"08", "09"}
        else ()
    )
    required_metrics = {
        "projection_scope",
        "projection_version",
        "wrinkle_segment_count",
        "wrinkle_centerline_length_px",
        "valid_skin_area_px",
        "primary_concentration_region",
    }
    required_units = {
        "wrinkle_segment_count",
        "wrinkle_centerline_length_px",
        "valid_skin_area_px",
    }
    projection_artifacts = tuple(projection.artifacts) if projection is not None else ()
    projection_valid = bool(
        projection is not None
        and projection_regions
        and tuple(projection.projection_scope_region_names) == expected_region_names
        and projection_metrics.get("projection_scope") == expected_scope
        and projection_metrics.get("projection_version") == expected_version
        and required_metrics <= set(projection_metrics)
        and required_units <= set(projection.units)
        and isinstance(projection_denominator, (int, float))
        and not isinstance(projection_denominator, bool)
        and projection_denominator > 0
        and all(
            region_name_in_group(module_id, str(row.get("analysis_region", "")))
    )


def adapt_fast3_fixture(result: Fast3StructuredResult) -> Doctor11EvidenceSnapshot:
    """Demote the historical Fast3 monolith to a gated regression fixture."""

    channels = _channel_states_from_fast3(result)
    modules = []
    for legacy_module in result.modules:
        gated = tuple(
            gate_cross_channel_head(
                _head_from_fast3(legacy_module.requirement_id, head, channels), channels
            )
            for head in legacy_module.evidence_heads
        )
        modules.append(_module_from_heads(legacy_module.requirement_id, gated))
    return Doctor11EvidenceSnapshot(
        capture_alias=result.capture_alias,
        route="clinic_four_light",
        generated_at=result.generated_at,
        code_state_sha256=result.code_state_sha256,
        channel_status=channels,
        modules=tuple(modules),
        source_result_count=0,
        limitations=(
            "本快照由历史Fast3工程原型转换，只用于回归和调试。",
            "重复原九项的临时OpenCV规则不得作为产品权威结果。",
            "medical_ready_count固定为0/11。",
        ),
    )


def clinic_modality_bundle_from_fast3_fixture(
    result: Fast3StructuredResult,
    *,
    artifact_prefix: str = "",
) -> ClinicModalityEvidenceBundle:
    """Select only non-duplicating modality/debug heads from the Fast3 fixture.

    The temporary RGB acne and RGB wrinkle implementations are deliberately not
    selected.  Modules 06 and 08 therefore continue to use the real nine-result
    acne and balanced-wrinkle records; 365 fluorescence and PP enhancement are
    only auxiliary observations.
    """

    channels = _channel_states_from_fast3(result)
    by_module = {module.requirement_id: module for module in result.modules}

    def select(module_id: str, head_ids: set[str]) -> tuple[Doctor11EvidenceHead, ...]:
        return tuple(
            gate_cross_channel_head(
                _head_from_fast3(
                    module_id,
                    head,
                    channels,
                    artifact_prefix=artifact_prefix,
                ),
                channels,
            )
            for head in by_module[module_id].evidence_heads
            if head.head_id in head_ids
        )

    oil_heads = select(
        "02",
        {"RGBPPSurfaceGlossObservation", "UV365FollicularFluorescenceCandidate"},
    )
    fluorescence = next(
        (head for head in oil_heads if head.head_id == "UV365FollicularFluorescenceCandidate"),
        None,
    )
    module_heads: dict[str, tuple[Doctor11EvidenceHead, ...]] = {
        "01": select("01", {"PorePPEnhancementShadowV1"}),
        "02": oil_heads,
        "03": select("03", {"CPCombinedPigmentCandidate", "UV365IndependentFeatureObservation"}),
        "04": select("04", {"DiffuseRednessAfterLocalExclusionV1"}),
        "05": select("05", {"CPVascularLikeLinearStructure2D"}),
        "07": select(
            "07",
            {"DryFineLineAppearance2D", "DryFineLineAppearance2DPPEnhancementShadow"},
        ),
        "08": select("08", {"FrontWrinkleAppearance2DSupplementPPEnhancementShadow"}),
        "11": select("11", {"FrontContourAppearance2D"}),
    }
    if fluorescence is not None:
        module_heads["06"] = (
            fluorescence.model_copy(
                update={
                    "head_id": "AcneAuxiliary365FollicularFluorescenceObservation",
                    "title": "365毛囊相关荧光独立辅助证据",
