def _verify_artifact(
    input_root: Path,
    relative_path: str,
    expected_size: int,
    expected_hash: str,
) -> str | None:
    try:
        root = input_root.resolve(strict=True)
    except (FileNotFoundError, OSError):
        return "CAPTURE_ROOT_NOT_AVAILABLE"
    try:
        target = (root / relative_path).resolve(strict=True)
    except (FileNotFoundError, OSError):
        return "CHANNEL_FILE_NOT_AVAILABLE"
    if not target.is_relative_to(root):
        return "CHANNEL_FILE_PATH_ESCAPE"
    if not target.is_file():
        return "CHANNEL_FILE_NOT_REGULAR"
    if target.stat().st_size != expected_size:
        return "CHANNEL_FILE_SIZE_MISMATCH"
    if file_sha256(target) != expected_hash:
        return "CHANNEL_FILE_HASH_MISMATCH"
    return None


def _device_gate_reason(
    bundle: CaptureBundle,
    manifest: SignedCaptureManifest,
    registries: FrozenRegistrySet,
) -> str | None:
    if bundle.device_profile_id is None or bundle.device_profile_sha256 is None:
        return "DEVICE_PROFILE_REFERENCE_MISSING"
    profile = registries.devices.find(bundle.device_profile_id)
    if profile is None:
        return "DEVICE_PROFILE_NOT_REGISTERED"
    if profile.content_sha256() != bundle.device_profile_sha256:
        return "DEVICE_PROFILE_HASH_MISMATCH"
    if manifest.key_id not in profile.manifest_key_ids:
        return "MANIFEST_KEY_NOT_ALLOWED_FOR_DEVICE"
    if bundle.viewpoint not in profile.approved_viewpoints:
        return "VIEWPOINT_NOT_REGISTERED_FOR_DEVICE"
    for channel in bundle.channels:
        if channel.role not in profile.supported_channels:
            return "CHANNEL_ROLE_NOT_SUPPORTED_BY_DEVICE"
        if profile.device_channel_name(channel.role) != channel.device_channel_name:
            return "DEVICE_CHANNEL_ROLE_MAPPING_MISMATCH"
    if bundle.device_model != profile.device_model:
        return "DEVICE_MODEL_MISMATCH"
    if bundle.firmware_version != profile.firmware_version:
        return "DEVICE_FIRMWARE_MISMATCH"
    if bundle.calibration_version != profile.calibration_version:
        return "DEVICE_CALIBRATION_MISMATCH"
    return None


def _channel_observations(
    *,
    bundle: CaptureBundle,
    evidence: CaptureValidationEvidence,
    input_root: Path,
) -> tuple[ChannelObservation, ...]:
    observations: list[ChannelObservation] = []
    rgb = bundle.channel(ChannelRole.RGB)
    assert rgb is not None
    observations.append(
        ChannelObservation(
            role=ChannelRole.RGB,
            state=ChannelState.AVAILABLE,
            artifact_sha256=rgb.artifact.sha256,
            independent_observation_allowed=True,
        )
    )
    for role in _CHANNEL_ORDER[1:]:
        channel = bundle.channel(role)
        if channel is None:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.ABSENT,
                    independent_observation_allowed=False,
                    reason_codes=("CHANNEL_ABSENT",),
                )
            )
            continue
        file_error = _verify_artifact(
            input_root,
            channel.artifact.relative_path,
            channel.artifact.size_bytes,
            channel.artifact.sha256,
        )
        channel_evidence = evidence.channel(role)
        if file_error is not None:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.QC_FAILED,
                    artifact_sha256=channel.artifact.sha256,
                    independent_observation_allowed=False,
                    reason_codes=(file_error,),
                )
            )
            continue
        if channel_evidence is None:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.QC_FAILED,
                    artifact_sha256=channel.artifact.sha256,
                    independent_observation_allowed=False,
                    reason_codes=("CHANNEL_QC_EVIDENCE_MISSING",),
                )
            )
            continue
        if not channel_evidence.qc_passed:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.QC_FAILED,
                    artifact_sha256=channel.artifact.sha256,
                    independent_observation_allowed=False,
                    reason_codes=channel_evidence.reason_codes or ("CHANNEL_QC_FAILED",),
                )
            )
            continue
        if channel_evidence.registration.status is not RegistrationStatus.PASSED:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.REGISTRATION_FAILED,
                    artifact_sha256=channel.artifact.sha256,
                    independent_observation_allowed=True,
                    registration=channel_evidence.registration,
                    reason_codes=tuple(
                        dict.fromkeys(
                            (
                                *channel_evidence.reason_codes,
                                *channel_evidence.registration.reason_codes,
                            )
                        )
                    ),
                )
            )
            continue
        if channel_evidence.algorithm_passed is False:
            observations.append(
                ChannelObservation(
                    role=role,
                    state=ChannelState.ALGORITHM_FAILED,
                    artifact_sha256=channel.artifact.sha256,
                    independent_observation_allowed=True,
                    registration=channel_evidence.registration,
                    reason_codes=channel_evidence.reason_codes
                    or ("CHANNEL_ALGORITHM_FAILED",),
                )
            )
            continue
        observations.append(
            ChannelObservation(
                role=role,
                state=ChannelState.AVAILABLE,
                artifact_sha256=channel.artifact.sha256,
                independent_observation_allowed=True,
                registration=channel_evidence.registration,
                reason_codes=channel_evidence.reason_codes,
            )
        )
    return tuple(observations)


