def main() -> int:
    parser = argparse.ArgumentParser(
        description="Doctor V2 stage2 internal route/QC gate; never runs algorithms or Word generation"
    )
    parser.add_argument("--route", required=True, choices=[item.value for item in CaptureRoute])
    parser.add_argument("--input-root", required=True, type=Path)
    parser.add_argument("--consumer-bundle", type=Path)
    parser.add_argument("--consumer-qc-evidence", type=Path)
    parser.add_argument("--clinic-manifest", type=Path)
    parser.add_argument("--signed-qc-attestation", type=Path)
    args = parser.parse_args()

    route = CaptureRoute(args.route)
    common = {
        "route": route,
        "input_root": args.input_root,
    }
    if route is CaptureRoute.CONSUMER_RGB:
        if (
            args.consumer_bundle is None
            or args.consumer_qc_evidence is None
            or args.clinic_manifest is not None
            or args.signed_qc_attestation is not None
        ):
            parser.error(
                "consumer_rgb requires --consumer-bundle and --consumer-qc-evidence; "
                "clinic arguments are forbidden"
            )
        decision = prepare_capture_run(
            **common,
            consumer_bundle=_read_json(args.consumer_bundle),
            qc_evidence=_read_json(args.consumer_qc_evidence),
        )
    else:
        if (
            args.clinic_manifest is None
            or args.signed_qc_attestation is None
            or args.consumer_bundle is not None
            or args.consumer_qc_evidence is not None
        ):
            parser.error(
