                "consumer arguments are forbidden"
            )
        decision = prepare_capture_run(
            **common,
            clinic_manifest=_read_json(args.clinic_manifest),
            signed_qc_attestation=_read_json(args.signed_qc_attestation),
        )

    print(decision.model_dump_json(indent=2))
    return 0 if decision.accepted else 2


