#!/usr/bin/env python3
from __future__ import annotations

"""Local internal auto-routing entry for Doctor V2 delivery.

The command consumes already accepted nine-result output.  It does not alter
or replace the Worker v1 API.  It infers a route only from an authenticated
exact role set, never from filenames, colours, or directory contents.
"""

import argparse
import json
import re
import sys
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from src.doctor_v2.dual_route_runner import (  # noqa: E402
    DoctorV2AutoRunRequest,
    DoctorV2AutoRunner,
    dual_route_code_state,
)


def _sha256(value: str) -> str:
    if re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise argparse.ArgumentTypeError("value must be a lowercase SHA-256")
    return value


def main() -> int:
    parser = argparse.ArgumentParser(description="Doctor V2 automatic dual-route local delivery")
    parser.add_argument(
        "--input-role",
        required=True,
        action="append",
        choices=(
            "RGB_M", "PP_M", "CP_M", "365_M",
            "RGB_L", "PP_L", "CP_L", "365_L",
            "RGB_R", "PP_R", "CP_R", "365_R",
        ),
    )
    parser.add_argument("--signed-manifest-sha256", type=_sha256)
    parser.add_argument("--capture-alias", required=True)
    parser.add_argument("--nine-review-root", required=True, type=Path)
    parser.add_argument("--clinic-modality-root", type=Path)
    parser.add_argument("--clinic-modality-fallback-root", type=Path)
    parser.add_argument("--formal-user", required=True, type=Path)
    parser.add_argument("--formal-doctor", required=True, type=Path)
    parser.add_argument("--formal-structured", required=True, type=Path)
    parser.add_argument("--formal-trace", required=True, type=Path)
    parser.add_argument("--output-root", required=True, type=Path)
    parser.add_argument("--code-state-sha256", type=_sha256)
    parser.add_argument("--expected-rgb-nine-result-sha256", type=_sha256)
    args = parser.parse_args()
    result = DoctorV2AutoRunner().run(
        DoctorV2AutoRunRequest(
            input_roles=tuple(args.input_role),
            signed_manifest_sha256=args.signed_manifest_sha256,
            capture_alias=args.capture_alias,
            nine_review_root=args.nine_review_root,
            clinic_modality_root=args.clinic_modality_root,
            clinic_modality_fallback_root=args.clinic_modality_fallback_root,
            formal_artifacts={
                "user_docx": args.formal_user,
                "doctor_docx": args.formal_doctor,
                "structured_json": args.formal_structured,
                "trace_json": args.formal_trace,
            },
            output_root=args.output_root,
            code_state_sha256=args.code_state_sha256 or dual_route_code_state()[1],
            expected_rgb_nine_result_sha256=args.expected_rgb_nine_result_sha256,
        )
    )
    print(
        json.dumps(
            {
                "route": result.route,
                "capture_alias": result.capture_alias,
                "rgb_nine_result_sha256": result.rgb_nine_result_sha256,
                "delivery_receipt": str(result.delivery_receipt),
                "route_receipt": str(result.route_receipt),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
from __future__ import annotations

import hashlib
import json
import re
import sys
import zipfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Any
from xml.etree import ElementTree as ET

import cv2
import numpy as np
from docx import Document


PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from src.doctor_v2.canonical import canonical_json_bytes, file_sha256  # noqa: E402
from src.doctor_v2.doctor11_contracts import (  # noqa: E402
    Doctor11EvidenceSnapshot,
    DoctorV2DeliveryBundle,
)
from src.doctor_v2.dual_route_runner import dual_route_code_state  # noqa: E402


ROOT = PROJECT_ROOT / "test-output/doctor-v2/final-dual-route-r9c"
ALIASES = ("clinic28-25", "clinic28-09", "clinic28-23")
BASELINE_ROOT = PROJECT_ROOT / "test-output/doctor-v2/w4-formal-reports-20260814-r8"
BASELINE_STEMS = {
    "clinic28-25": "AISIA_面部多指标检测报告_AISIA-CLINIC28-25-W2",
    "clinic28-09": "AISIA_面部多指标检测报告_AISIA-20260814-0001",
    "clinic28-23": "AISIA_面部多指标检测报告_AISIA-20260814-0002",
}
ABSOLUTE_TOKENS = ("/home/", "/mnt/", "\\\\wsl", "C:\\", "D:\\")
W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
CONSTRUCT_REGIONS = {
    "08": {
        "forehead",
        "glabella",
        "image_left_crow_feet",
        "image_right_crow_feet",
    },
    "09": {
        "image_left_nasolabial",
        "image_right_nasolabial",
        "image_left_marionette",
        "image_right_marionette",
    },
}


def _contains_absolute(value: Any) -> bool:
    if isinstance(value, dict):
        return any(_contains_absolute(item) for item in value.values())
    if isinstance(value, (list, tuple)):
        return any(_contains_absolute(item) for item in value)
    return isinstance(value, str) and value.startswith(ABSOLUTE_TOKENS)


def _docx_media_hashes(archive: zipfile.ZipFile) -> set[str]:
    return {
        hashlib.sha256(archive.read(name)).hexdigest()
        for name in archive.namelist()
        if name.startswith("word/media/") and not name.endswith("/")
    }


def _bookmark_names(document_xml: bytes) -> set[str]:
    root = ET.fromstring(document_xml)
    return {
        node.attrib[f"{{{W_NS}}}name"]
        for node in root.findall(f".//{{{W_NS}}}bookmarkStart")
        if node.attrib.get(f"{{{W_NS}}}name") not in {None, "_GoBack"}
    }


def _layout_fingerprint(path: Path) -> dict[str, Any]:
    with zipfile.ZipFile(path) as archive:
        document = archive.read("word/document.xml")
        root = ET.fromstring(document)
        sections = []
        for section in root.findall(f".//{{{W_NS}}}sectPr"):
            page_size = section.find(f"{{{W_NS}}}pgSz")
            margins = section.find(f"{{{W_NS}}}pgMar")
            sections.append(
                {
                    "page_size": dict(page_size.attrib) if page_size is not None else {},
                    "margins": dict(margins.attrib) if margins is not None else {},
                }
            )
        internal = {}
        for name in ("word/styles.xml", "word/numbering.xml", "word/header1.xml", "word/footer1.xml"):
            internal[name] = hashlib.sha256(archive.read(name)).hexdigest() if name in archive.namelist() else None
        return {
            "internal": internal,
            "sections": sections,
            "bookmarks": sorted(_bookmark_names(document)),
        }


def _verify_docx(path: Path, baseline: Path, module11_sha256: str) -> dict[str, Any]:
    document = Document(path)
    visible = "\n".join(paragraph.text for paragraph in document.paragraphs)
    visible += "\n" + "\n".join(
        cell.text for table in document.tables for row in table.rows for cell in row.cells
    )
    if any(token in visible for token in ABSOLUTE_TOKENS):
        raise ValueError(f"visible absolute path in {path}")
    if "四光源采集与配准" not in visible or "四光源辅助证据" not in visible:
        raise ValueError(f"clinic formal report lacks four-light evidence: {path}")
    if not all(token in visible for token in ("RGB", "PP", "CP", "365")):
        raise ValueError(f"clinic formal report lacks a channel role: {path}")
    if not (
        "不可用于生成深度、体积或紧致度结论" in visible
        and "暂不评分" in visible
    ):
        raise ValueError(f"module11 limitation is absent: {path}")
    with zipfile.ZipFile(path) as archive:
        relationship_xml = archive.read("word/_rels/document.xml.rels").decode("utf-8")
        media = [
            name for name in archive.namelist()
            if name.startswith("word/media/") and not name.endswith("/")
        ]
        orphan = [name for name in media if Path(name).name not in relationship_xml]
        if orphan:
            raise ValueError(f"orphan media in {path}: {orphan}")
        for name in ("word/document.xml", "docProps/core.xml"):
            xml = archive.read(name).decode("utf-8", errors="strict")
            if any(token in xml for token in ABSOLUTE_TOKENS):
                raise ValueError(f"absolute path in DOCX XML: {path}/{name}")
        if module11_sha256 not in _docx_media_hashes(archive):
            raise ValueError(f"module11 image hash is absent from {path}")
    current_layout = _layout_fingerprint(path)
    baseline_layout = _layout_fingerprint(baseline)
    if current_layout != baseline_layout:
        raise ValueError(f"VISIA2 formal layout fingerprint drifted: {path}")
    if len(current_layout["bookmarks"]) != 13:
        raise ValueError(f"formal report bookmark count drifted: {path}")
    return {
        "sha256": file_sha256(path),
        "paragraph_count": len(document.paragraphs),
        "table_count": len(document.tables),
        "media_count": len(media),
        "bookmark_count": len(current_layout["bookmarks"]),
        "layout_matches_r8_baseline": True,
        "module11_image_embedded": True,
    }


def _verify_construct_support(sample: Path, module: Any, head_id: str) -> None:
    head = next(head for head in module.evidence_heads if head.head_id == head_id)
    expected = CONSTRUCT_REGIONS[module.requirement_id]
    if {str(row.get("region_id")) for row in head.regions} != expected:
        raise ValueError(f"module {module.requirement_id} PP construct regions drifted")
    if (
        head.denominator_name
        != f"doctor_{module.requirement_id}_construct_support_area_px"
        or not isinstance(head.denominator_value, (int, float))
        or head.denominator_value <= 0
    ):
        raise ValueError(f"module {module.requirement_id} PP construct denominator drifted")
    support_artifacts = [
        artifact for artifact in head.artifacts
        if artifact.relative_path.endswith("_support.png")
    ]
    mask_artifacts = [
        artifact for artifact in head.artifacts
        if artifact.relative_path.endswith("_mask.png")
        and not artifact.relative_path.endswith("_support.png")
    ]
    if len(support_artifacts) != 1 or len(mask_artifacts) != 1:
        raise ValueError(f"module {module.requirement_id} PP support artifacts drifted")
    support_artifact = support_artifacts[0]
    if head.support_mask_id != support_artifact.sha256:
        raise ValueError(f"module {module.requirement_id} support id is not the support artifact")
    support = cv2.imread(str(sample / support_artifact.relative_path), cv2.IMREAD_GRAYSCALE)
    evidence = cv2.imread(str(sample / mask_artifacts[0].relative_path), cv2.IMREAD_GRAYSCALE)
    if support is None or evidence is None or support.shape != (1024, 1024) or evidence.shape != support.shape:
        raise ValueError(f"module {module.requirement_id} PP support image is invalid")
    support_count = int(np.count_nonzero(support))
    if support_count != int(head.denominator_value):
        raise ValueError(f"module {module.requirement_id} PP support denominator mismatched its mask")
    if np.any((evidence > 0) & ~(support > 0)):
        raise ValueError(f"module {module.requirement_id} PP evidence escaped construct support")


def _verify_alias(alias: str) -> dict[str, Any]:
    sample = ROOT / alias
    reports = sample / "reports"
    delivery = DoctorV2DeliveryBundle.model_validate_json(
        (reports / "delivery_receipt.json").read_text(encoding="utf-8")
    )
    if delivery.capture_alias != alias:
        raise ValueError("delivery alias mismatch")
    by_role = {artifact.artifact_role: artifact for artifact in delivery.artifacts}
    for artifact in delivery.artifacts:
        path = (reports / artifact.relative_path).resolve(strict=True)
        if not path.is_relative_to(reports.resolve()) or path.is_symlink():
            raise ValueError("delivery artifact escaped its report root")
        if path.stat().st_size != artifact.size_bytes or file_sha256(path) != artifact.sha256:
            raise ValueError(f"delivery artifact drifted: {alias}/{artifact.artifact_role}")

    snapshot_path = reports / by_role["doctor11_snapshot"].relative_path
    snapshot_raw = json.loads(snapshot_path.read_text(encoding="utf-8"))
    if _contains_absolute(snapshot_raw):
        raise ValueError("snapshot contains an absolute path")
    snapshot = Doctor11EvidenceSnapshot.model_validate(snapshot_raw)
    if snapshot.route != "clinic_four_light" or snapshot.medical_ready_count != "0/11":
        raise ValueError("snapshot route or medical state drifted")
    if any(value is not None for value in (snapshot.formal_score, snapshot.formal_grade, snapshot.overall_recommendation)):
        raise ValueError("snapshot emitted a prohibited new formal output")
    for module in snapshot.modules:
        if any(value is not None for value in (module.score, module.grade, module.recommendation)):
            raise ValueError(f"module {module.requirement_id} emitted a prohibited formal output")
        for head in module.evidence_heads:
            for artifact in head.artifacts:
                path = (sample / artifact.relative_path).resolve(strict=True)
                if not path.is_relative_to(sample.resolve()) or path.is_symlink():
                    raise ValueError("evidence artifact escaped sample root")
                if path.stat().st_size != artifact.size_bytes or file_sha256(path) != artifact.sha256:
                    raise ValueError(f"evidence artifact drifted: {alias}/{artifact.relative_path}")
            if head.registration_status == "FAILED" and any(
                value is not None for value in (head.overlap, head.co_location, head.fusion)
            ):
                raise ValueError("failed registration leaked a cross-channel field")

    modules_by_id = {module.requirement_id: module for module in snapshot.modules}
    _verify_construct_support(
        sample,
        modules_by_id["08"],
        "StableWrinklePPEnhancementObservation",
    )
    _verify_construct_support(
        sample,
        modules_by_id["09"],
        "GroovePPEnhancementObservation",
    )

    if alias in {"clinic28-09", "clinic28-23"}:
        uv = next(row for row in snapshot.channel_status if row.role == "365")
        if uv.registration_status != "FAILED":
            raise ValueError("fixed failed-365 sample unexpectedly passed")

    structured_path = reports / by_role["formal_structured_data"].relative_path
    structured = json.loads(structured_path.read_text(encoding="utf-8"))
    if _contains_absolute(structured):
        raise ValueError("formal structured data contains an absolute path")
    channels = structured.get("采集与质量信息", {}).get("四光源通道", [])
    if [row.get("通道") for row in channels] != ["RGB", "PP", "CP", "365"]:
        raise ValueError("formal structured channel overview drifted")
    modules = {str(row.get("模块编号")): row for row in structured.get("检测模块", [])}
    if len(modules) != 11:
        raise ValueError("formal structured module count drifted")
    module05 = modules["05"]
    if module05.get("报告资格") == "NOT_REPORTABLE" and module05.get("核心指标"):
        raise ValueError("module05 leaked candidate metrics while not reportable")
    module11 = modules["11"]
    if (
        module11.get("模块状态") != "NOT_ASSESSABLE"
        or module11.get("报告资格") != "NOT_REPORTABLE"
        or module11.get("综合得分") is not None
    ):
        raise ValueError("module11 formal state drifted")
    module11_sha = str(module11.get("二维补充图SHA256", ""))
    if re.fullmatch(r"[0-9a-f]{64}", module11_sha) is None:
        raise ValueError("module11 supplement hash is absent")

    stem = BASELINE_STEMS[alias]
    baseline_root = BASELINE_ROOT / alias
    user_path = reports / by_role["formal_user"].relative_path
    doctor_path = reports / by_role["formal_doctor"].relative_path
    user = _verify_docx(
        user_path,
        baseline_root / f"{stem}_用户精简版.docx",
        module11_sha,
    )
    doctor = _verify_docx(
        doctor_path,
        baseline_root / f"{stem}_医生详细版.docx",
        module11_sha,
    )
    debug_path = reports / by_role["engineering_debug"].relative_path
    debug_text = "\n".join(p.text for p in Document(debug_path).paragraphs)
    if "工程调试报告" not in debug_text or "未评分" not in debug_text:
        raise ValueError("debug report role or boundary drifted")
    route_receipt = json.loads((sample / "dual_route_receipt.json").read_text())
    if (
        route_receipt.get("route") != "clinic_four_light"
        or route_receipt.get("clinic_auxiliary_changes_rgb_results") is not False
        or route_receipt.get("worker_v1_modified") is not False
    ):
        raise ValueError("dual-route receipt drifted")
    return {
        "capture_alias": alias,
        "rgb_nine_result_sha256": route_receipt["rgb_nine_result_sha256"],
        "snapshot_sha256": file_sha256(snapshot_path),
        "module_count": len(snapshot.modules),
        "formal_user": user,
        "formal_doctor": doctor,
        "engineering_debug_sha256": file_sha256(debug_path),
        "module11_image_sha256": module11_sha,
        "four_light_auxiliary_present": True,
        "medical_ready_count": "0/11",
    }


def main() -> int:
    if not ROOT.is_dir():
        raise FileNotFoundError(ROOT)
    code_rows, code_hash = dual_route_code_state()
    samples = [_verify_alias(alias) for alias in ALIASES]
    manifest = {
        "schema_version": "doctor_v2_dual_route_r9_run_manifest_v1",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "dataset_id": "Clinic-Fast3",
        "route": "clinic_four_light",
        "captures": list(ALIASES),
        "code_state": code_rows,
        "code_state_sha256": code_hash,
        "input_view_count": 12,
        "vendor_exact_input_view_count": 36,
        "report_counts": {"formal_user": 3, "formal_doctor": 3, "engineering_debug": 3},
        "samples": samples,
        "vendor_exact_receipt": "docs/DOCTOR_V2_VENDOR_EXACT_R9_RECEIPT.json",
        "vendor_findings_promoted": 0,
        "medical_ready_count": "0/11"
    }
    manifest_path = ROOT / "run_manifest.json"
    manifest_path.write_bytes(canonical_json_bytes(manifest) + b"\n")
    verification = {
        "schema_version": "doctor_v2_dual_route_r9_verification_receipt_v1",
        "verified_at": datetime.now(timezone.utc).isoformat(),
        "status": "PASS",
        "run_manifest_sha256": file_sha256(manifest_path),
        "sample_count": 3,
        "snapshot_count": 3,
        "docx_count": 9,
        "formal_layout_matches_r8_baseline": True,
        "formal_four_light_auxiliary_present": True,
        "module11_snapshot_word_hash_consistent": True,
        "failed_registration_cross_fields_null": True,
        "worker_v1_modified": False,
        "medical_ready_count": "0/11",
        "not_proven": [
            "medical validation",
            "new score calibration",
            "Vendor Exact runtime acceptance",
            "firmness measurement",
            "accuracy or generalization"
        ]
    }
    receipt_path = ROOT / "verification_receipt.json"
    receipt_path.write_bytes(canonical_json_bytes(verification) + b"\n")
    print(
        json.dumps(
            {
                "status": "PASS",
                "run_manifest_sha256": file_sha256(manifest_path),
                "verification_receipt_sha256": file_sha256(receipt_path),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
