class AuthoritativeModuleResult(_Frozen):
    """The only Doctor11 result that a formal projection may render.

    A module can aggregate several independently preserved evidence heads, but
    it must expose exactly one primary artifact to either formal report.  This
    contract deliberately keeps presentation eligibility separate from
    medical readiness and from the frozen legacy score profile.
    """

    requirement_id: str = Field(pattern=r"^(0[1-9]|1[01])$")
    title: str
    presentation_tier: Literal[
        "FORMAL_PRIMARY", "FORMAL_SUPPLEMENT", "UNAVAILABLE"
    ]
    source_head_ids: tuple[str, ...]
    source_channels: tuple[ChannelRole, ...]
    primary_artifact: EvidenceArtifact | None = None
    metrics: tuple[dict[str, Any], ...] = ()
    summary: str
    reason_codes: tuple[str, ...] = ()
    score: None = None
    grade: None = None
    recommendation: None = None

    @model_validator(mode="after")
    def validate_single_formal_result(self) -> "AuthoritativeModuleResult":
        if self.presentation_tier == "UNAVAILABLE":
            if self.primary_artifact is not None or not self.reason_codes:
                raise ValueError("unavailable formal result needs a reason and no artifact")
        elif self.primary_artifact is None:
            raise ValueError("formal result requires exactly one primary artifact")
        if not self.source_head_ids or not self.source_channels:
            raise ValueError("formal result must retain its evidence provenance")
        if self.requirement_id == "11" and self.presentation_tier == "FORMAL_PRIMARY":
            raise ValueError("relative geometry may only be a formal supplement")
        return self


