    def select(module_id: str, head_ids: set[str]) -> tuple[Doctor11EvidenceHead, ...]:
        return tuple(
            gate_cross_channel_head(
                _head_from_fast3(
                    module_id,
                    head,
                    channels,
                    artifact_prefix=artifact_prefix,
                ),
                channels,
            )
            for head in by_module[module_id].evidence_heads
            if head.head_id in head_ids
        )

    oil_heads = select(
        "02",
        {"RGBPPSurfaceGlossObservation", "UV365FollicularFluorescenceCandidate"},
    )
    fluorescence = next(
        (head for head in oil_heads if head.head_id == "UV365FollicularFluorescenceCandidate"),
        None,
    )
    module_heads: dict[str, tuple[Doctor11EvidenceHead, ...]] = {
        "01": select("01", {"PorePPEnhancementShadowV1"}),
